import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";
const token = Deno.env.get("SONGCRAFT_WEB_DEPLOY_TOKEN") ?? "";
const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json" } });
const bytes = (base64: string) => Uint8Array.from(atob(base64), (entry) => entry.charCodeAt(0));
Deno.serve(async (request) => {
  if (request.method !== "POST") return json({ error: "Použij POST." }, 405);
  const input = await request.json().catch(() => null) as { deployToken?: string; action?: string; path?: string; base64?: string; contentType?: string } | null;
  if (input?.deployToken !== token) return json({ error: "Neplatné nasazovací ověření." }, 401);
  const url = Deno.env.get("SUPABASE_URL"); const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!url || !serviceKey) return json({ error: "Chybí servisní konfigurace hostingu." }, 500);
  const service = createClient(url, serviceKey);
  if (input.action === "reset") { const { error } = await service.storage.emptyBucket("songcraft-web"); return error ? json({ error: error.message }, 400) : json({ ok: true }); }
  if (input.action !== "upload" || !input.path || !input.base64 || !input.contentType || input.path.includes("..") || input.path.startsWith("/") || input.path.includes(".git")) return json({ error: "Neplatný soubor pro statický web." }, 400);
  await service.storage.from("songcraft-web").remove([input.path]);
  const { error } = await service.storage.from("songcraft-web").upload(input.path, bytes(input.base64), { contentType: input.contentType, cacheControl: "3600", upsert: false });
  return error ? json({ error: error.message }, 400) : json({ ok: true, path: input.path, contentType: input.contentType });
});
